package services

import (
	"fmt"
	"sort"
	"strings"

	"github.com/go-go-golems/css-visual-diff/internal/cssvisualdiff/modes"
)

type AgentBriefOptions struct {
	Question   string
	Evidence   modes.CompareResult
	MaxBullets int
}

type AgentBriefResult struct {
	Question             string            `json:"question"`
	Bullets              []string          `json:"bullets"`
	PixelDiffPercent     float64           `json:"pixelDiffPercent"`
	ChangedPropertyCount int               `json:"changedPropertyCount"`
	Artifacts            map[string]string `json:"artifacts,omitempty"`
}

func BuildAgentBrief(opts AgentBriefOptions) AgentBriefResult {
	maxBullets := opts.MaxBullets
	if maxBullets <= 0 {
		maxBullets = 8
	}

	bullets := []string{}
	if opts.Evidence.PixelDiff.ChangedPercent > 0 {
		bullets = append(bullets, fmt.Sprintf("Visual drift is %.2f%% of pixels at threshold %d.", opts.Evidence.PixelDiff.ChangedPercent, opts.Evidence.PixelDiff.Threshold))
	}

	for _, diff := range opts.Evidence.ComputedDiffs {
		if strings.TrimSpace(diff.Original) == strings.TrimSpace(diff.React) {
			continue
		}
		bullets = append(bullets, fmt.Sprintf("Change `%s` from `%s` to `%s`.", diff.Property, safeValue(diff.Original), safeValue(diff.React)))
		if len(bullets) >= maxBullets {
			break
		}
	}

	if len(bullets) < maxBullets {
		winnerBullets := summarizeWinnerDiffs(opts.Evidence.WinnerDiffs)
		for _, bullet := range winnerBullets {
			bullets = append(bullets, bullet)
			if len(bullets) >= maxBullets {
				break
			}
		}
	}

	artifacts := map[string]string{}
	if opts.Evidence.URL1.ElementScreenshot != "" {
		artifacts["left"] = opts.Evidence.URL1.ElementScreenshot
	}
	if opts.Evidence.URL2.ElementScreenshot != "" {
		artifacts["right"] = opts.Evidence.URL2.ElementScreenshot
	}
	if opts.Evidence.PixelDiff.DiffComparisonPath != "" {
		artifacts["comparison"] = opts.Evidence.PixelDiff.DiffComparisonPath
	}
	if opts.Evidence.PixelDiff.DiffOnlyPath != "" {
		artifacts["diff"] = opts.Evidence.PixelDiff.DiffOnlyPath
	}
	if len(artifacts) == 0 {
		artifacts = nil
	}

	return AgentBriefResult{
		Question:             strings.TrimSpace(opts.Question),
		Bullets:              bullets,
		PixelDiffPercent:     opts.Evidence.PixelDiff.ChangedPercent,
		ChangedPropertyCount: len(opts.Evidence.ComputedDiffs),
		Artifacts:            artifacts,
	}
}

func RenderAgentBriefText(result AgentBriefResult) string {
	var lines []string
	if strings.TrimSpace(result.Question) != "" {
		lines = append(lines, result.Question)
	}
	for _, bullet := range result.Bullets {
		lines = append(lines, "- "+bullet)
	}
	if len(lines) == 0 {
		return ""
	}
	return strings.Join(lines, "\n") + "\n"
}

func summarizeWinnerDiffs(diffs []modes.WinnerDiff) []string {
	bullets := []string{}
	seen := map[string]struct{}{}
	for _, diff := range diffs {
		left := strings.TrimSpace(diff.Original.Selector)
		right := strings.TrimSpace(diff.React.Selector)
		if left == right {
			continue
		}
		if left == "" && right == "" {
			continue
		}
		key := diff.Property + "|" + left + "|" + right
		if _, ok := seen[key]; ok {
			continue
		}
		seen[key] = struct{}{}
		bullets = append(bullets, fmt.Sprintf("Winning rule for `%s` changed from `%s` to `%s`.", diff.Property, safeValue(left), safeValue(right)))
	}
	sort.Strings(bullets)
	return bullets
}

func safeValue(value string) string {
	value = strings.TrimSpace(value)
	if value == "" {
		return "(empty)"
	}
	return value
}

package modes

import (
	"context"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"

	"github.com/go-go-golems/css-visual-diff/internal/cssvisualdiff/ai"
	"github.com/go-go-golems/css-visual-diff/internal/cssvisualdiff/config"
)

type AIReviewResult struct {
	Sections []AISectionReview `json:"sections"`
}

type AISectionReview struct {
	Name     string     `json:"name"`
	Selector string     `json:"selector"`
	Question string     `json:"question"`
	Original AIResponse `json:"original"`
	React    AIResponse `json:"react"`
}

type AIResponse struct {
	Screenshot string    `json:"screenshot"`
	Answer     ai.Answer `json:"answer"`
}

func RunAIReview(ctx context.Context, cfg *config.Config) error {
	capturePath := filepath.Join(cfg.Output.Dir, "capture.json")
	data, err := os.ReadFile(capturePath)
	if err != nil {
		return fmt.Errorf("ai-review requires capture.json: %w", err)
	}

	var capture CaptureResult
	if err := json.Unmarshal(data, &capture); err != nil {
		return err
	}

	client := ai.NoopClient{}
	result := AIReviewResult{}

	for i, section := range cfg.Sections {
		if section.OCRQuestion == "" {
			continue
		}

		review := AISectionReview{
			Name:     section.Name,
			Selector: section.Selector,
			Question: section.OCRQuestion,
		}

		if i < len(capture.Original.Sections) {
			origShot := capture.Original.Sections[i].Screenshot
			review.Original.Screenshot = origShot
			ans, err := client.AnswerQuestion(ctx, origShot, section.OCRQuestion)
			if err != nil {
				ans.Error = err.Error()
			}
			review.Original.Answer = ans
		}
		if i < len(capture.React.Sections) {
			reactShot := capture.React.Sections[i].Screenshot
			review.React.Screenshot = reactShot
			ans, err := client.AnswerQuestion(ctx, reactShot, section.OCRQuestion)
			if err != nil {
				ans.Error = err.Error()
			}
			review.React.Answer = ans
		}

		result.Sections = append(result.Sections, review)
	}

	if cfg.Output.WriteJSON {
		if err := writeJSON(filepath.Join(cfg.Output.Dir, "ai-review.json"), result); err != nil {
			return err
		}
	}
	if cfg.Output.WriteMarkdown {
		if err := writeAIMarkdown(filepath.Join(cfg.Output.Dir, "ai-review.md"), result); err != nil {
			return err
		}
	}

	return nil
}

func writeAIMarkdown(path string, result AIReviewResult) error {
	content := "# css-visual-diff AI Review Report\n\n"
	for _, s := range result.Sections {
		content += fmt.Sprintf("## %s\n\n", s.Name)
		content += fmt.Sprintf("Question: %s\n\n", s.Question)
		content += "### Original\n\n"
		content += fmt.Sprintf("Screenshot: %s\n\n", s.Original.Screenshot)
		content += fmt.Sprintf("Answer: %s\n\n", s.Original.Answer.Text)
		if s.Original.Answer.Error != "" {
			content += fmt.Sprintf("Error: %s\n\n", s.Original.Answer.Error)
		}
		content += "### React\n\n"
		content += fmt.Sprintf("Screenshot: %s\n\n", s.React.Screenshot)
		content += fmt.Sprintf("Answer: %s\n\n", s.React.Answer.Text)
		if s.React.Answer.Error != "" {
			content += fmt.Sprintf("Error: %s\n\n", s.React.Answer.Error)
		}
	}
	return os.WriteFile(path, []byte(content), 0o644)
}

