}

type CompareInputs struct {
	URL1      string   `json:"url1"`
	Selector1 string   `json:"selector1"`
	WaitMS1   int      `json:"wait_ms1"`
	URL2      string   `json:"url2"`
	Selector2 string   `json:"selector2"`
	WaitMS2   int      `json:"wait_ms2"`
