	if s.A != other.A {
		if s.A > other.A {
			return 1
		}
		return -1
	}
	if s.B != other.B {
		if s.B > other.B {
			return 1
		}
		return -1
	}
	if s.C != other.C {
		if s.C > other.C {
			return 1
		}
		return -1
	}
	return 0
}

func (s Specificity) String() string {
	return fmt.Sprintf("%d,%d,%d", s.A, s.B, s.C)
}

func (s Specificity) Add(other Specificity) Specificity {
	return Specificity{
		A: s.A + other.A,
		B: s.B + other.B,
		C: s.C + other.C,
	}
